// Generated by vibes-espmatter – updates over Matter: the hub is the OTA provider of its devices. Every few
// minutes it asks the vibes-espmatter app which of them their owner started an update for there, finds
// them by their UniqueID, tells them (AnnounceOTAProvider) and streams the image from the app to them over
// BDX, block by block – the hub keeps none of it. How far each got goes back to the app.
#include "espm_matter.h"
#include "espm_updates.h"
#include "espm_web.h"
#include "espm_config.h"

#include <cstdio>
#include <cstring>
#include <esp_log.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#include <freertos/task.h>
#include <sdkconfig.h>

#include <esp_matter.h>
#include <esp_matter_controller_client.h>
#include <esp_matter_controller_cluster_command.h>
#include <esp_matter_controller_read_command.h>
#include <esp_matter_ota_bdx_sender.h>

#include <app-common/zap-generated/cluster-objects.h>
#include <app/InteractionModelEngine.h>
#include <app/clusters/ota-provider/ota-provider-cluster.h>
#include <app/clusters/ota-provider/ota-provider-delegate.h>
#include <app/data-model-provider/Provider.h>
#include <app/dynamic_server/AccessControl.h>
#include <app/data-model/Decode.h>
#include <controller/CHIPDeviceControllerFactory.h>
#include <crypto/RandUtils.h>
#include <lib/support/BitFlags.h>
#include <platform/CHIPDeviceLayer.h>
